//! PLAN-791 V02 — byte-frozen compatibility arms of the CURRENT (pre-extraction)
//! `auto-gen` behavior, pinned against goldens generated by the old
//! implementation at worktree base e4ac72a62 (library-path cases were
//! blessed from the same old implementation via the 9c4780c54 replay,
//! review R1 F-791-R1-01). These tests are the oracle the auto-gen-core
//! extraction must keep green without reblessing.
//!
//! Known frozen quirks (do NOT "fix" here — they are the contract):
//! - `DataSource::AutoFile`/`AutoCode` never expose evaluated variables to
//!   templates (interpreter scope mismatch): variable templates fail with
//!   `Undefined variable: ...` collected in the report. Only
//!   `DataSource::Atom` (globals via merge_atom) renders.
//! - `lib_files` definitions likewise never reach templates (asserted by
//!   `lib_files_definitions_invisible_to_templates`); a missing lib file is
//!   a TOP-LEVEL error before any template runs.
//! - A template `use ...` line is filtered from the rendered output and does
//!   not fail on its own (`use` resolution is unwired); non-empty
//!   `lib_paths` are inert.
//! - `GeneratorConfig::fstr_note` is inert for the shared-interpreter render
//!   path (the DataLoader interpreter keeps the default note), so `@var`
//!   stays literal with `fstr_note: '@'`.
//! - legacy `AutoGen` writes guard-fed output with lines joined by `\n` and
//!   no trailing newline, and strips only an EMBEDDED `.at.` from mold names
//!   (a trailing `.at` survives).

mod common;

use auto_gen::{CodeGenerator, DataSource, GenerationSpec, GeneratorConfig, TemplateSpec};
use common::{sample_atom, templates_dir};
use std::fs;
use std::path::{Path, PathBuf};

fn fixture_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn data_dir() -> PathBuf {
    fixture_dir().join("data")
}

fn lib_dir() -> PathBuf {
    fixture_dir().join("lib")
}

fn goldens_dir() -> PathBuf {
    fixture_dir().join("goldens")
}

fn update_goldens() -> bool {
    std::env::var("UPDATE_GOLDENS").is_ok_and(|v| v == "1")
}

fn copy_tree(src: &Path, dst: &Path) {
    fs::create_dir_all(dst).unwrap();
    for entry in fs::read_dir(src).unwrap() {
        let entry = entry.unwrap();
        let target = dst.join(entry.file_name());
        if entry.path().is_dir() {
            copy_tree(&entry.path(), &target);
        } else {
            fs::copy(entry.path(), target).unwrap();
        }
    }
}

fn rel_files(root: &Path) -> Vec<PathBuf> {
    let mut out = Vec::new();
    fn walk(root: &Path, dir: &Path, out: &mut Vec<PathBuf>) {
        for entry in fs::read_dir(dir).unwrap() {
            let entry = entry.unwrap();
            let path = entry.path();
            if path.is_dir() {
                walk(root, &path, out);
            } else {
                out.push(path.strip_prefix(root).unwrap().to_path_buf());
            }
        }
    }
    walk(root, root, &mut out);
    out.sort();
    out
}

/// Marker stored in `goldens/<case>/` when the frozen output tree is EMPTY:
/// git cannot track empty directories, so the golden for "nothing was
/// written" is an explicit, committed marker file instead.
const EMPTY_TREE_MARKER: &str = ".empty-tree";

/// Assert every file under `produced_dir` equals the byte-frozen golden tree
/// `goldens/<case>` (same relative file set, same bytes; an empty frozen
/// tree is represented by the `.empty-tree` marker). With
/// `UPDATE_GOLDENS=1` the golden tree is rewritten from `produced_dir`
/// instead (bless mode; never set this in CI/plain runs).
fn assert_tree_matches_golden(case: &str, produced_dir: &Path) {
    let golden_root = goldens_dir().join(case);
    if update_goldens() {
        if golden_root.exists() {
            fs::remove_dir_all(&golden_root).unwrap();
        }
        fs::create_dir_all(&golden_root).unwrap();
        if rel_files(produced_dir).is_empty() {
            fs::write(golden_root.join(EMPTY_TREE_MARKER), b"").unwrap();
        } else {
            copy_tree(produced_dir, &golden_root);
        }
        eprintln!("[goldens] updated case '{case}' from {produced_dir:?}");
        return;
    }
    assert!(
        golden_root.is_dir(),
        "golden tree missing for case '{case}': {}",
        golden_root.display()
    );
    if golden_root.join(EMPTY_TREE_MARKER).exists() {
        assert!(
            rel_files(produced_dir).is_empty(),
            "golden case '{case}' froze an EMPTY output tree, but files were produced"
        );
        assert_eq!(
            rel_files(&golden_root),
            vec![PathBuf::from(EMPTY_TREE_MARKER)],
            "empty-tree marker must be the only golden entry for case '{case}'"
        );
        return;
    }
    let produced: Vec<PathBuf> = rel_files(produced_dir);
    let expected: Vec<PathBuf> = rel_files(&golden_root);
    assert_eq!(
        produced, expected,
        "file set differs for golden case '{case}'"
    );
    for rel in &expected {
        let got = fs::read(produced_dir.join(rel)).unwrap();
        let want = fs::read(golden_root.join(rel)).unwrap();
        assert_eq!(
            got,
            want,
            "byte mismatch for golden case '{case}' / {}",
            rel.display()
        );
    }
}

fn run_case(
    case: &str,
    out_dir: &std::path::Path,
    data: DataSource,
    templates: Vec<TemplateSpec>,
) -> auto_gen::GenReport {
    run_case_with_libs(case, out_dir, data, templates, vec![], vec![])
}

fn run_case_with_libs(
    case: &str,
    out_dir: &std::path::Path,
    data: DataSource,
    templates: Vec<TemplateSpec>,
    lib_files: Vec<PathBuf>,
    lib_paths: Vec<PathBuf>,
) -> auto_gen::GenReport {
    let mut gen = CodeGenerator::new(GeneratorConfig {
        output_dir: out_dir.to_path_buf(),
        ..Default::default()
    });
    let spec = GenerationSpec {
        data_source: data,
        templates,
        lib_files,
        lib_paths,
    };
    let report = gen
        .generate(&spec)
        .unwrap_or_else(|e| panic!("generate returned top-level error: {e}"));
    assert_tree_matches_golden(case, out_dir);
    report
}

fn tpl(name: &str) -> TemplateSpec {
    TemplateSpec {
        template_path: templates_dir().join(name),
        output_name: None,
        rename: false,
    }
}

/// Atom data + multi-template batch: default output naming strips one
/// trailing `.at` from the template file stem (`hello.txt.at` → `hello.txt`)
/// and `$ for` code lines render over merged globals.
#[test]
fn atom_batch_golden() {
    let tmp = tempfile::tempdir().unwrap();
    let report = run_case(
        "atom_batch",
        tmp.path(),
        DataSource::Atom(sample_atom()),
        vec![tpl("hello.txt.at"), tpl("listing.txt.at")],
    );
    assert_eq!(report.files_generated.len(), 2);
    assert!(report.errors.is_empty());
}

/// Builder path: `add_template` output_name override wins over template
/// file naming (`static.txt.at` → `renamed.md`).
#[test]
fn builder_output_name_golden() {
    let tmp = tempfile::tempdir().unwrap();
    let spec = CodeGenerator::builder()
        .data_source(DataSource::Atom(sample_atom()))
        .add_template(templates_dir().join("static.txt.at"), "renamed.md")
        .create_spec()
        .unwrap();
    let mut gen = CodeGenerator::new(GeneratorConfig {
        output_dir: tmp.path().to_path_buf(),
        ..Default::default()
    });
    let report = gen.generate(&spec).unwrap();
    assert_eq!(report.files_generated.len(), 1);
    assert!(report.errors.is_empty());
    assert_tree_matches_golden("builder_output_name", tmp.path());
}

/// AutoFile data with `let` statements: render error is COLLECTED in the
/// report (batch semantics), no output file is written.
#[test]
fn autofile_let_error_reported() {
    let tmp = tempfile::tempdir().unwrap();
    let report = run_case(
        "autofile_let_error",
        tmp.path(),
        DataSource::AutoFile(data_dir().join("lets.at")),
        vec![tpl("hello.txt.at")],
    );
    assert!(report.files_generated.is_empty());
    assert_eq!(report.errors.len(), 1);
    let msg = format!("{}", report.errors[0]);
    assert!(
        msg.contains("Undefined variable: name"),
        "unexpected error: {msg}"
    );
    assert!(
        msg.contains("template:hello.txt"),
        "error must be attributed to the template: {msg}"
    );
}

/// AutoCode data in atom syntax hits the same scope-mismatch arm.
#[test]
fn autocode_atom_error_reported() {
    let tmp = tempfile::tempdir().unwrap();
    let report = run_case(
        "autocode_atom_error",
        tmp.path(),
        DataSource::AutoCode("name: \"x\"\nversion: 2\n".to_string()),
        vec![tpl("hello.txt.at")],
    );
    assert!(report.files_generated.is_empty());
    assert_eq!(report.errors.len(), 1);
    assert!(format!("{}", report.errors[0]).contains("Undefined variable"));
}

/// A missing data file is a TOP-LEVEL error (stage boundary: load failures
/// abort the whole generate call, they never appear in the report).
#[test]
fn missing_data_top_level_error() {
    let tmp = tempfile::tempdir().unwrap();
    let mut gen = CodeGenerator::new(GeneratorConfig {
        output_dir: tmp.path().to_path_buf(),
        ..Default::default()
    });
    let spec = GenerationSpec {
        data_source: DataSource::AutoFile(data_dir().join("missing.at")),
        templates: vec![tpl("hello.txt.at")],
        lib_files: vec![],
        lib_paths: vec![],
    };
    let err = match gen.generate(&spec) {
        Err(e) => e,
        Ok(_) => panic!("expected DataLoadError, generate succeeded"),
    };
    assert!(
        matches!(err, auto_gen::GenError::DataLoadError { .. }),
        "expected DataLoadError, got: {err}"
    );
}

/// A missing template file is a PER-TEMPLATE error inside the report.
#[test]
fn missing_template_error_in_report() {
    let tmp = tempfile::tempdir().unwrap();
    let report = run_case(
        "missing_template",
        tmp.path(),
        DataSource::Atom(sample_atom()),
        vec![tpl("does_not_exist.txt.at")],
    );
    assert!(report.files_generated.is_empty());
    assert_eq!(report.errors.len(), 1);
    assert!(
        matches!(
            &report.errors[0],
            auto_gen::GenError::TemplateLoadError { .. }
        ),
        "expected TemplateLoadError, got: {:?}",
        report.errors[0]
    );
}

/// fstr_note quirk: with `fstr_note: '@'` the shared-interpreter render keeps
/// the default note, so `@name` stays literal in the output bytes.
#[test]
fn fstr_note_shared_interp_quirk() {
    let tmp = tempfile::tempdir().unwrap();
    let mut gen = CodeGenerator::new(GeneratorConfig {
        output_dir: tmp.path().to_path_buf(),
        fstr_note: '@',
        ..Default::default()
    });
    let spec = GenerationSpec {
        data_source: DataSource::Atom(sample_atom()),
        templates: vec![tpl("at_note.txt.at")],
        lib_files: vec![],
        lib_paths: vec![],
    };
    let report = gen.generate(&spec).unwrap();
    assert!(report.errors.is_empty());
    assert_tree_matches_golden("fstr_note_quirk", tmp.path());
}

/// F-791-R1-01: a NON-EMPTY `lib_files` entry loads (top-level stage) but its
/// definitions never reach the template — the call fails with the frozen
/// scope-mismatch arm, collected per-template, zero files written.
#[test]
fn lib_files_definitions_invisible_to_templates() {
    let tmp = tempfile::tempdir().unwrap();
    let report = run_case_with_libs(
        "lib_files_invisible",
        tmp.path(),
        DataSource::Atom(sample_atom()),
        vec![tpl("calls_lib.txt.at")],
        vec![lib_dir().join("util.at")],
        vec![],
    );
    assert!(report.files_generated.is_empty());
    assert_eq!(report.errors.len(), 1);
    let msg = format!("{}", report.errors[0]);
    assert!(
        msg.contains("Undefined variable: greet"),
        "expected the lib function to be invisible to the template, got: {msg}"
    );
}

/// F-791-R1-01: a template `use ...` line is filtered from the rendered
/// output and does not fail on its own; non-empty `lib_paths` are inert
/// (use resolution is unwired). Golden blessed by the OLD implementation.
#[test]
fn template_use_statement_filtered_from_output() {
    let tmp = tempfile::tempdir().unwrap();
    let report = run_case_with_libs(
        "use_line_filtered",
        tmp.path(),
        DataSource::Atom(sample_atom()),
        vec![tpl("uses_lib.txt.at")],
        vec![],
        vec![lib_dir()],
    );
    assert_eq!(report.files_generated.len(), 1);
    assert!(report.errors.is_empty());
    let out = fs::read_to_string(tmp.path().join("uses_lib.txt")).unwrap();
    assert!(
        !out.contains("use util"),
        "use line must be filtered from output: {out}"
    );
}

/// F-791-R1-01: a MISSING lib file is a TOP-LEVEL TemplateLoadError raised
/// before any template runs — existing outputs keep their bytes and no new
/// files appear.
#[test]
fn missing_lib_file_top_level_error_and_no_writes() {
    let tmp = tempfile::tempdir().unwrap();
    let sentinel = b"previous run bytes\n".to_vec();
    fs::write(tmp.path().join("hello.txt"), &sentinel).unwrap();

    let mut gen = CodeGenerator::new(GeneratorConfig {
        output_dir: tmp.path().to_path_buf(),
        ..Default::default()
    });
    let spec = GenerationSpec {
        data_source: DataSource::Atom(sample_atom()),
        templates: vec![tpl("hello.txt.at")],
        lib_files: vec![lib_dir().join("no_such_lib.at")],
        lib_paths: vec![],
    };
    let err = match gen.generate(&spec) {
        Err(e) => e,
        Ok(_) => panic!("expected TemplateLoadError for missing lib file"),
    };
    assert!(
        matches!(&err, auto_gen::GenError::TemplateLoadError { path, .. } if path.ends_with("no_such_lib.at")),
        "expected TemplateLoadError for the lib file, got: {err}"
    );
    // The template batch never ran: the previous output is untouched.
    assert_eq!(fs::read(tmp.path().join("hello.txt")).unwrap(), sentinel);
    assert!(
        fs::read_dir(tmp.path()).unwrap().count() == 1,
        "no other files may appear on a failed lib load"
    );
}

/// Legacy deprecated API: `AutoGen::gen_all` with a pre-existing output file
/// feeds guarded sections from the old file, joins lines with `\n` (NO
/// trailing newline) and strips only an embedded `.at.` from the mold name
/// (`legacy.at.txt` → `legacy.txt`).
#[test]
fn legacy_autogen_golden() {
    let tmp = tempfile::tempdir().unwrap();
    fs::write(
        tmp.path().join("legacy.txt"),
        "old header\n/// ---------- begin of guard: <u1> ---\nHAND EDITED\n/// ---------- end of guard: ---\nold tail\n",
    )
    .unwrap();

    #[allow(deprecated)]
    let ag = auto_gen::AutoGen::new()
        .data(sample_atom())
        .out(tmp.path().to_str().unwrap())
        .note('@')
        .mold({
            #[allow(deprecated)]
            auto_gen::Mold::from_file(templates_dir().join("legacy.at.txt").to_str().unwrap())
        });

    #[allow(deprecated)]
    {
        let _ = ag.gen_all();
    }
    // Only the fed output file is compared (gen_all echoes data to stdout).
    let fed = tmp.path().join("legacy.txt");
    let golden = goldens_dir().join("legacy_autogen").join("legacy.txt");
    if update_goldens() {
        fs::create_dir_all(golden.parent().unwrap()).unwrap();
        fs::copy(&fed, &golden).unwrap();
        eprintln!("[goldens] updated case 'legacy_autogen'");
        return;
    }
    let got = fs::read(&fed).unwrap();
    let want = fs::read(&golden).unwrap();
    assert_eq!(got, want, "legacy AutoGen fed output bytes changed");
}

/// Legacy deprecated API: `gen_str` concatenates rendered molds.
#[test]
fn legacy_gen_str() {
    #[allow(deprecated)]
    let ag = auto_gen::AutoGen::new()
        .data(sample_atom())
        .note('@')
        .mold({
            #[allow(deprecated)]
            auto_gen::Mold::new("x.at.txt", "value @version\n")
        });
    #[allow(deprecated)]
    let out = ag.gen_str();
    assert_eq!(out, "value 2\n");
}

/// CLI: static template (no lookups) renders through the AutoFile data path
/// and exits 0 with byte-identical output.
#[test]
fn cli_static_template_ok() {
    let tmp = tempfile::tempdir().unwrap();
    let exe = env!("CARGO_BIN_EXE_autogen");
    let out = std::process::Command::new(exe)
        .arg("generate")
        .arg("-d")
        .arg(data_dir().join("lets.at"))
        .arg("-t")
        .arg(templates_dir().join("static.txt.at"))
        .arg("-o")
        .arg(tmp.path())
        .output()
        .unwrap();
    assert_eq!(
        out.status.code(),
        Some(0),
        "stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&out.stdout),
        String::from_utf8_lossy(&out.stderr)
    );
    let stdout = String::from_utf8_lossy(&out.stdout);
    assert!(stdout.contains("Generated 1 files"), "stdout: {stdout}");
    assert_tree_matches_golden("cli_static", tmp.path());
}

/// CLI: a template referencing variables the AutoFile loader cannot expose
/// fails per-template — exit 1 after reporting, no output file.
#[test]
fn cli_failing_lookup_exit1() {
    let tmp = tempfile::tempdir().unwrap();
    let exe = env!("CARGO_BIN_EXE_autogen");
    let out = std::process::Command::new(exe)
        .arg("generate")
        .arg("-d")
        .arg(data_dir().join("lets.at"))
        .arg("-t")
        .arg(templates_dir().join("hello.txt.at"))
        .arg("-o")
        .arg(tmp.path())
        .output()
        .unwrap();
    assert_eq!(out.status.code(), Some(1));
    let stdout = String::from_utf8_lossy(&out.stdout);
    let stderr = String::from_utf8_lossy(&out.stderr);
    assert!(stdout.contains("Generated 0 files"), "stdout: {stdout}");
    assert!(stderr.contains("Errors occurred"), "stderr: {stderr}");
    assert!(stderr.contains("Undefined variable"), "stderr: {stderr}");
    assert!(fs::read_dir(tmp.path()).unwrap().count() == 0);
}
